def transform(grid):
    if not grid or not grid[0]:
        return grid
    bg = grid[0][0]
    h, w = len(grid), len(grid[0])

    # Determine the bottom-most row index for each color
    max_r = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color != bg:
                if color not in max_r:
                    max_r[color] = r
                else:
                    max_r[color] = max(max_r[color], r)

    # Initialize output grid with background
    out = [[bg for _ in range(w)] for _ in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                color = grid[r][c]
                mr = max_r[color]

                # Apply rule: Shift right if r < mr (not bottom-most row)
                # If r == mr, stay in place (or shift 0)
                # Shift target column: min(c+1, w-1) ensures boundary clamping
                # (If c=w-1 shifts to w-1, effectively staying)

                if r < mr:
                    target_col = min(c + 1, w - 1)
                    out[r][target_col] = color
                else:
                    out[r][c] = color

    return out
